def cx(n): return "simple" if n<50 else "moderate" if n<=200 else "complex"
nodes=[];edges=[]
for p,(s,t,fns) in F.items():
    r=fx[p]; nodes.append({"id":f"file:{p}","type":"file","name":p.split('/')[-1],"filePath":p,"summary":s,"tags":t,"complexity":cx(r['nonEmptyLines'])})
    exp={e['name'] for e in r['exports']}
    for f in r['functions']:
        if f['name'] not in fns: continue
        nid=f"function:{p}:{f['name']}"
        nodes.append({"id":nid,"type":"function","name":f['name'],"filePath":p,"lineRange":[f['startLine'],f['endLine']],"summary":fns[f['name']],"tags":t[:3],"complexity":cx(f['endLine']-f['startLine'])})
        edges.append({"source":f"file:{p}","target":nid,"type":"contains","direction":"forward","weight":1.0})
        if f['name'] in exp: edges.append({"source":f"file:{p}","target":nid,"type":"exports","direction":"forward","weight":0.8})
    for tgt in imp[p]:
        edges.append({"source":f"file:{p}","target":f"file:{tgt}","type":"imports","direction":"forward","weight":0.7})
# a few confident cross-file calls
for src,tgt in [("src/features/auth/login-page.tsx","src/data/api/errors.ts"),("src/features/branches/branch-dialog.tsx","src/data/api/errors.ts"),("src/features/bundles/bundle-dialog.tsx","src/data/api/errors.ts"),("src/features/delivery/zone-dialog.tsx","src/data/api/errors.ts"),("src/features/inventory/item-dialog.tsx","src/data/api/errors.ts")]:
    fn=[n for n in nodes if n['filePath']==src and n['type']=='function'][-1]['id']
    edges.append({"source":fn,"target":"function:src/data/api/errors.ts:getErrorMessage","type":"calls","direction":"forward","weight":0.8})
print(len(nodes),len(edges),sum(1 for e in edges if e['type']=='imports'))
parts=3
paths=sorted(F); sz=math.ceil(len(paths)/parts)
for k in range(parts):
    ps=set(paths[k*sz:(k+1)*sz]); ns=[n for n in nodes if n['filePath'] in ps]; ids={n['id'] for n in ns}
    es=[e for e in edges if e['source'] in ids]
    json.dump({"nodes":ns,"edges":es},open(f"/Users/shawket/Desktop/MadarDashboard/.ua/intermediate/batch-5-part-{k+1}.json","w"),indent=1)
    print(k+1,len(ns),len(es))
